local ParseUtils = CS.ParseUtils
local parse_number = parse_number
local parse_string = parse_string

local metaTable = {
    __index = function(t, k)
        if k ~= "cv" then
            return nil
        end
        if SettingVoiceMgr == nil then
            SettingVoiceMgr = import("Game.UI.Setting.SettingVoiceMgr")
            SettingVoiceMgr:Init()
        end
        local value = rawget(t, k.."_"..SettingVoiceMgr:GetCurrentVoiceTag())
        if not string.isEmpty(value) then
            -- print("[i18n配音CV] ", k.."_"..SettingVoiceMgr:GetCurrentVoiceTag(), value)
            return value
        else
            -- print("[i18n配音CV] 没有找到 ", k.."_"..SettingVoiceMgr:GetCurrentVoiceTag(), " 默认使用日配 ", rawget(t, k.."_jp"))
            return rawget(t, k.."_jp")
        end
    end
}


